print(Vector(1, 2) + Vector(3, 4))
print(Vector(1, 2) == Vector(1, 2))

class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def __len__(self):
        return len(self._items)

    def __bool__(self):
        return len(self._items) > 0

    def __contains__(self, item):
        return item in self._items

s = Stack()
print(bool(s), len(s))
s.push('a')
print(bool(s), len(s), 'a' in s)

class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current < 0:
            raise StopIteration
        value = self.current
        self.current -= 1
        return value

for n in Countdown(3):
    print(n, end=' ')
